import numpy as np
els=[]; coords=[]; edges=[]
def unit(v): return np.array(v)/np.linalg.norm(v)
def add(e,p,parent=None):
 i=len(els);els.append(e);coords.append(np.array(p))
 if parent is not None: edges.append((parent,i))
 return i
def ortho(v):
 v=unit(v); a=np.cross(v,[0,0,1.])
 if np.linalg.norm(a)<0.1: a=np.cross(v,[0,1.,0])
 a=unit(a);return a,np.cross(v,a)
def tetra(inward, phase=0):
 v=unit(inward);a,b=ortho(v)
 return [-v/3+np.sqrt(8/9)*(np.cos(phase+2*np.pi*k/3)*a+np.sin(phase+2*np.pi*k/3)*b) for k in range(3)]
def methyl(p,parent,phase):
 c=add('C',p,parent)
 for d in tetra(coords[parent]-p,phase): add('H',p+1.095*d,c)
 return c
co=add('Co',[0.,0.,0.])
for ang,twist in [(30,25),(150,-25)]:
 th=np.deg2rad(ang);r=np.array([np.cos(th),np.sin(th),0.])
 n=add('N',1.93*r,co)
 p=np.array([-r[1],r[0],0.])*np.cos(np.deg2rad(twist))+np.array([0,0,1])*np.sin(np.deg2rad(twist))
 for j,sign in enumerate([-1,1]):
  d=0.5*r+sign*np.sqrt(.75)*p
  si=add('Si',coords[n]+1.74*d,n)
  for k,sd in enumerate(tetra(-d, np.deg2rad(25+j*60))):
   methyl(coords[si]+1.86*sd,si,np.deg2rad(k*35))
r=np.array([0.,-1.,0.]);n=add('N',1.68*r,co)
c=add('C',coords[n]+1.46*r,n)
for k,d in enumerate(tetra(-r, np.pi/6)):
 methyl(coords[c]+1.53*d,c,np.deg2rad(20*k))
with open('initial.xyz','w') as f:
 f.write(f'{len(els)}\nCobalt bis(bis(trimethylsilyl)amide) tert-butylimido anion\n')
 for e,p in zip(els,coords): f.write(f'{e} {p[0]:.9f} {p[1]:.9f} {p[2]:.9f}\n')
np.savez('connectivity.npz',edges=np.array(edges),els=np.array(els))
print(len(els))
